import{_ as n,C as i,o as t,c as s,a3 as o,b as l,w as r,a as d,E as c,a4 as g}from"./chunks/framework.BzWmN0d8.js";const w=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1788354533000}'),u={name:"guide/introduction.md"};function h(p,e,m,f,y,b){const a=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><code>lograil</code> is a high-performance, secure logging library for <strong>Electron</strong> (main + renderer), <strong>Node.js</strong>, and the <strong>Web</strong>. It gives you one zero-config <code>logger</code> that auto-detects its runtime, plus a layered pipeline of filters, processors, formatters, and transports you can extend as needed.</p><p>This page explains what <code>lograil</code> is, why it exists, when to reach for it, and the core concepts you&#39;ll meet throughout the guides. If you just want to start logging, jump to <a href="./getting-started">Getting Started</a>.</p><h2 id="why-lograil" tabindex="-1">Why lograil <a class="header-anchor" href="#why-lograil" aria-label="Permalink to &quot;Why lograil&quot;">​</a></h2><p>Most logging libraries treat Electron as an afterthought: you wire up IPC by hand, duplicate config across processes, and hope the renderer&#39;s logs actually reach a file. <code>lograil</code> is built for that reality from the ground up:</p><ul><li><strong>One logger, every runtime.</strong> The same <code>import { logger } from &#39;lograil&#39;</code> works untouched in the main process, the renderer, Node, and the browser. The runtime adapter detects where it runs and binds to the right transport automatically.</li><li><strong>Secure by default in Electron.</strong> Renderer logs are forwarded to the main process over IPC — they never touch the filesystem from an untrusted context. This fits Electron&#39;s <code>contextIsolation</code> + preload security model (see <a href="./runtime-electron">Electron</a>).</li><li><strong>Structured, not stringly-typed.</strong> Every log is a frozen <code>LogEntry</code> carrying a level, message, timestamp, <code>context</code> (persistent request-scoped fields), <code>metadata</code> (per-entry details injected by processors), and arbitrary structured fields. Transports can render it as JSON, a console line, or a live UI without re-parsing. See <a href="./context">Context &amp; Metadata</a> for when to use each field.</li><li><strong>Composable pipeline.</strong> Filter → process → format → transport. Add sampling, redaction, or custom fields without forking the library.</li><li><strong>Hot-path safe.</strong> Logging never throws into your application code. A failing transport or subscriber is isolated and reported, never breaks the caller.</li></ul><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>You&#39;re building an <strong>Electron app</strong> and want main + renderer logs unified into files and the console without hand-rolled IPC.</li><li>You want <strong>structured logs</strong> (levels, context, fields) that survive across processes and runtimes.</li><li>You need <strong>pluggable outputs</strong> — files, console, OpenTelemetry, a live in-app viewer — behind a single API.</li><li>You care about <strong>performance and safety</strong> in latency-sensitive code paths.</li></ul><p>If you only need a tiny <code>console.log</code> wrapper for a Node script, <code>lograil</code> may be more than you need. For anything multi-process, multi-runtime, or production-facing, it earns its place.</p><h2 id="core-concepts-at-a-glance" tabindex="-1">Core concepts at a glance <a class="header-anchor" href="#core-concepts-at-a-glance" aria-label="Permalink to &quot;Core concepts at a glance&quot;">​</a></h2><p><code>lograil</code> is organized as a pipeline. A log moves through these stages:</p>',11)),(t(),l(g,null,{default:r(()=>[c(a,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5BYour%20code%5D%20--%3E%20B%5BLogger%5D%0A%20%20B%20--%3E%20C%5BPipeline%3A%20Filter%20%2F%20Processor%20%2F%20Formatter%5D%0A%20%20C%20--%3E%20D%5BTransports%5D%0A%20%20D%20--%3E%20E%5BConsole%20%2F%20File%20%2F%20OTLP%20%2F%20Live%20UI%5D%0A%20%20F%5BContext%5D%20-.enrich.-%3E%20B%0A%20%20G%5BRuntime%20Adapter%5D%20-.bind.-%3E%20D%0A%20%20H%5BPlugins%5D%20-.extend.-%3E%20B%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ul><li><strong>LogEntry</strong> — the immutable, frozen record of a single log event: <code>level</code>, <code>message</code>, <code>timestamp</code>, <code>context</code>, <code>fields</code>, and metadata. It is shared by reference (zero-copy) and must never be mutated after creation.</li><li><strong>Level</strong> — <code>trace</code> &lt; <code>debug</code> &lt; <code>info</code> &lt; <code>warn</code> &lt; <code>error</code> &lt; <code>fatal</code>. The logger and each transport can enforce its own threshold.</li><li><strong>Context</strong> — ambient key/value data (request id, user id, session) attached automatically to every entry via async-local storage, without threading it through every call.</li><li><strong>Pipeline</strong> — the ordered chain of <strong>filters</strong> (drop or keep), <strong>processors</strong> (enrich/redact/sample), and <strong>formatters</strong> (turn an entry into a string or bytes) that shape each entry before it ships.</li><li><strong>Transports</strong> — the destinations: console, rotating files, OpenTelemetry (OTLP), a live in-app stream, or your own. A logger can have many.</li><li><strong>Runtime adapters</strong> — detect the environment (Electron main/renderer, Node, Web) and bind the right defaults so the same code runs everywhere.</li><li><strong>Plugins</strong> — extend the logger with cross-cutting behavior (tracing, metrics, custom hooks) without touching core.</li></ul><p>These concepts are explored in depth in <a href="./architecture">Architecture</a>. The <a href="/lograil/api/">API Reference</a> documents every type and method.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./getting-started">Getting Started</a> — install and emit your first structured logs.</li><li><a href="./configuration">Configuration</a> — levels, pipeline, and transports.</li><li><a href="./transports">Transports</a> — built-in and custom destinations.</li><li><a href="./runtime-electron">Electron</a> — secure main/renderer logging setup.</li></ul>',4))])}const _=n(u,[["render",h]]);export{w as __pageData,_ as default};
